	    ld   a, (GM_COUNT)
	    cp   6
	    jr   c, __GM_DONE       ; not a frame interrupt
__GM_FRAME:
	    call __CPC_FH_RUN
__GM_DONE:
	    pop  bc
	    pop  af
	    ei
	    ret
	    ENDP

