	; -----------------------------------------------------------------------
	; Amstrad CPC -- keyboard matrix scan and key translation
	;
	; Shared by INKEY$ (inkey.asm) and the stdlib keys.bas (GetKeyScanCode,
	; MultiKeys). From the public documentation of the 8255 PPI, the
