	; __CB_SCAN_KEYS -- reads the 10 rows into CB_KEYS, straight from the
	; hardware, with interrupts off so the firmware's own keyboard scan (in
	; its interrupt handler) cannot interleave with this one; returns with
	; interrupts on.
