	    ld   a, h
	    ld   (__CBC_CH), a
	    call __CB_ADDR
	    ld   de, 0
	    ld   (__CBS_SKIP), de
	    ld   e, (ix+12)
	    ld   d, (ix+13)
	    or   a
	    ret
__CSP_CLIP:
	    ld   a, e
	    ld   (__CBS_K), a
	    ld   l, (ix+4)
	    ld   h, (ix+5)
	    ld   e, (ix+6)
	    ld   d, (ix+7)
	    ld   b, (ix+9)
	    ld   c, (ix+11)
