	    ld   l, a
	    ld   h, 0
	    ld   a, (__CBS_K)
	    dec  a
	    jr   z, __CSP_ONE1
	    add  hl, hl
__CSP_ONE1:
	    ld   (__CBS_SKIP), hl
	    ld   hl, 0              ; offset = SY * w + SX
	    ld   a, (__CBC_SY)
	    or   a
	    jr   z, __CSP_NOSY
