	    ld   d, 0
	    ld   b, a
__CSP_MUL:
	    add  hl, de
	    djnz __CSP_MUL
__CSP_NOSY:
	    ld   a, (__CBC_SX)
	    ld   e, a
	    ld   d, 0
	    add  hl, de
	    ld   a, (__CBS_K)
	    dec  a
	    jr   z, __CSP_ONE2
	    add  hl, hl
__CSP_ONE2:
