	    ld   a, d
	    or   e
	    jr   nz, __CSU_NO       ; clipped at a side (leaves D = 0 otherwise)
	    ld   a, (__CBC_CW)
	    cp   1
	    jr   z, __CSU_GO
	    ld   e, 2
	    cp   2
	    jr   z, __CSU_GO
	    ld   e, 4
	    cp   4
	    jr   z, __CSU_GO
	    ld   e, 6
	    cp   8
	    jr   nz, __CSU_NO
__CSU_GO:
	    add  hl, de
	    ld   e, (hl)
	    inc  hl
	    ld   d, (hl)
