	    ld   a, c
	    jr   __CFR_GO
__CFR_FULL:                 ; fewer than a full group left: all of them
	    ld   c, a               ; (A = rows left, 1-7)
	    xor  a
	    ld   (__CBC_CH), a
	    ld   a, c
__CFR_GO:
	    ld   bc, (__CBS_INN)
	    push bc
	    ret
__CFR_NEXT:
	    ld   a, (__CBC_CH)
	    or   a
	    ret  z
	    ld   a, h
	    sub  $40
	    ld   h, a
	    ld   bc, 80
	    add  hl, bc
	    jr   __CFR_GRP
	    ENDP


__CBS_INN: DEFW 0

__CBS_K:    DEFB 0
__CBS_SKIP: DEFW 0


