	    LOCAL __PP_ABSENT, __PP_DONE
	    call __PL_DI
	    ld   hl, $4000
	    ld   e, (hl)            ; E = the original byte
	    ld   a, e
	    or   $80
	    ld   d, a               ; D = test value, bit 7 set
	    ld   (hl), d
	    push de                 ; (E = the original byte, for later)
	    call __PL_UNLOCK_RAW    ; DE kept
	    call __PL_RMR
	    ld   e, a               ; E = the RMR value, for a machine with no ASIC
	    and  3
