	    ld   c, a
	    call PLXP               ; Z = RAM answered (RMR rewritten), NZ = Plus (paged out)
	    pop  de                 ; (flags kept)
	    ld   hl, $4000
	    ld   (hl), e            ; the byte back
	    jr   z, __PP_ABSENT
    ld   a, (PLUS_UNLK)     ; Plus: lock again unless the library had unlocked it
	    or   a
	    call z, __PL_LOCK_RAW
	    ld   a, 1
	    jr   __PP_DONE
__PP_ABSENT:
	    ld   a, 2
__PP_DONE:
