	    ld   b, 0
	    ld   hl, PLUS_DMAPS
	    add  hl, bc
	    ld   (hl), e
	    ret

PLUS_DMAEN: defb 0          ; enable bits written by the library
PLUS_DMAPS: defb 0, 0, 0    ; prescaler per channel

