	    ld   hl, __CPC_ISR
	    ld   ($0039), hl
	    ld   hl, 0
	    ld   (CPC_EXIT_VEC), hl
	    xor  a
	    ld   (RI_N), a
	    ld   (RI_IDX), a
	    ret

	; __RI_EXIT -- CPC_EXIT_VEC's routine (END's reset, interrupts off).
__RI_EXIT:
	    jp   __RI_STOP

; __RI_CLEAR -- RasterIntClear: all raster interrupts off, back to the
