	    push bc
	    push de
	    push hl
	    call __ERR_PUTC
	    pop  hl
	    pop  de
	    pop  bc
	    pop  af
	    ret
__ERR_PUTC:
	    PROC
	    LOCAL __EP_CH, __EP_G, __EP_ROW

	    ld   hl, (__BT_PUTC_VEC)    ; the full text renderer, if this program has it
	    ld   c, a
